import org.junit.jupiter.api.Test;

class BlakeTest {
    // Literals from Python hashlib.blake2b / blake2s (RFC 7693 appendix for "abc").
    private static byte[] seq(int n) {
        byte[] b = new byte[n];
        for (int i = 0; i < n; i++) {
            b[i] = (byte) i;
        }
        return b;
    }

    @Test
    void blake2bVectors() {
        assertEquals("ba80a53f981c4d0d6a2797b69f12f6e94c212f14685ac4b74b12bb6fdbffa2d17d87c5392aab792dc252d5de4533cc9518d38aa8dbf1925ab92386edd4009923",
                hashStr(new Blake2b(), "abc"));
        assertEquals("786a02f742015903c6c6fd852552d272912f4740e15847618a86e217f71f5419d25e1031afee585313896444934eb04b903a685b1448b755d56f701afe9be2ce",
                hashStr(new Blake2b(), ""));
    }

    @Test
    void blake2sVectors() {
        assertEquals("508c5e8c327c14e2e1a72ba34eeb452f37458b209ed63a294d999b4c86675982", hashStr(new Blake2s(), "abc"));
        assertEquals("69217a3079908094e11121d042354a7c1f55b6482ca1a51e1b250dfd1ed0eef9", hashStr(new Blake2s(), ""));
    }

    @Test
    void keyedVectors() {
        // Official-KAT style: key 00..3f (b) / 00..1f (s).
        Blake2b b = new Blake2b(64, seq(64));
        assertEquals("10ebb67700b1868efb4417987acf4690ae9d972fb7a590c2f02871799aaa4786b5e996e8f0f4eb981fc214b005f42d2ff4233499391653df7aefcbc13fc51568",
                Hex.encode(b.digest()));
        b.update(new byte[] {0});
        assertEquals("961f6dd1e4dd30f63901690c512e78e4b45e4742ed197c3c5e45c549fd25f2e4187b0bc9fe30492b16b0d0bc4ef9b0f34c7003fac09a5ef1532e69430234cebd",
                Hex.encode(b.digest()));
        Blake2s s = new Blake2s(32, seq(32));
        assertEquals("48a8997da407876b3d79c0d92325ad3b89cbb754d86ab71aee047ad345fd2c49", Hex.encode(s.digest()));
    }

    @Test
    void chainsCoverBlockBoundaries() {
        // Lengths 0..300 hit 127/128/129 and 255/256/257 (b) and 63/64/65 (s).
        assertEquals("3eb2aedcf22b05697871895739c0c4cbf094742175e5ed0b71e2b3d652b505f1251be936d131fc24e87eb848dd66a32c1ae4e0b8985bd1071e9e9d83dce9726a", chain(new Blake2b()));
        assertEquals("da4b7f1bcda6ddd6ecb2c2fd624799f9229959764676c07b1fdf73e9122b0c5c", chain(new Blake2s()));
        assertEquals("be3ab66c63b09f553cdf9df70c3c4ae54dfc6a16", chain(new Blake2b(20, seq(17))));
        assertEquals("7562df1a1592587638", chain(new Blake2s(9, seq(32))));
    }

    @Test
    void variableOutputLengthsChangeTheParameterBlock() {
        assertEquals("6b", hashStr(new Blake2b(1, null), "abc"));
        byte[] a200 = new byte[200];
        java.util.Arrays.fill(a200, (byte) 'a');
        Blake2b b = new Blake2b(33, null);
        b.update(a200);
        assertEquals("3570e6010e1ba1a8dce47cad256765308fdb6a6fdbe47bee4cb64d3f07b89a4d65", Hex.encode(b.digest()));
        Blake2s s = new Blake2s(17, null);
        s.update(a200);
        assertEquals("95b6910946f5d2512f9969e1f0b4221073", Hex.encode(s.digest()));
        assertEquals(33, b.digestLength());
    }

    @Test
    void millionAs() {
        Blake2b k = new Blake2b();
        byte[] block = new byte[1000];
        java.util.Arrays.fill(block, (byte) 'a');
        for (int i = 0; i < 1000; i++) {
            k.update(block);
        }
        assertEquals("98fb3efb7206fd19ebf69b6f312cf7b64e3b94dbe1a17107913975a793f177e1d077609d7fba363cbba00d05f7aa4e4fa8715d6428104c0a75643b0ff3fd3eaf", Hex.encode(k.digest()));
    }

    @Test
    void chunkingInvariantAndReuse() {
        Random rnd = new Random(7);
        for (int iter = 0; iter < 300; iter++) {
            byte[] data = new byte[rnd.nextInt(600)];
            rnd.nextBytes(data);
            byte[] key = rnd.nextBoolean() ? null : seq(1 + rnd.nextInt(32));
            int outLen = 1 + rnd.nextInt(32);
            Digest ref = iter % 2 == 0 ? new Blake2b(outLen, key) : new Blake2s(outLen, key);
            Digest test = iter % 2 == 0 ? new Blake2b(outLen, key) : new Blake2s(outLen, key);
            ref.update(data);
            byte[] expected = ref.digest();
            assertArrayEquals(expected, chunked(test, data, rnd), "iter=" + iter);
            // digest() reset must restore the keyed initial state, not just the buffer.
            assertArrayEquals(expected, chunked(test, data, rnd), "reuse iter=" + iter);
        }
    }

    @Test
    void keyChangesOutputAndKeyedEmptyDiffersFromUnkeyed() {
        byte[] k1 = seq(5);
        byte[] k2 = seq(5);
        k2[4] ^= 1;
        assertNotEquals(Hex.encode(new Blake2b(32, k1).digest()), Hex.encode(new Blake2b(32, k2).digest()));
        assertNotEquals(Hex.encode(new Blake2b(32, k1).digest()), Hex.encode(new Blake2b(32, null).digest()));
    }

    @Test
    void sizesAndValidation() {
        assertEquals(128, new Blake2b().blockLength());
        assertEquals(64, new Blake2b().digestLength());
        assertEquals(64, new Blake2s().blockLength());
        assertEquals(32, new Blake2s().digestLength());
        assertThrows(IllegalArgumentException.class, () -> new Blake2b(0, null));
        assertThrows(IllegalArgumentException.class, () -> new Blake2b(65, null));
        assertThrows(IllegalArgumentException.class, () -> new Blake2b(64, new byte[65]));
        assertThrows(IllegalArgumentException.class, () -> new Blake2s(0, null));
        assertThrows(IllegalArgumentException.class, () -> new Blake2s(33, null));
        assertThrows(IllegalArgumentException.class, () -> new Blake2s(32, new byte[33]));
        assertDoesNotThrow(() -> new Blake2b(64, new byte[64]));
        assertDoesNotThrow(() -> new Blake2s(32, new byte[32]));
        assertThrows(IndexOutOfBoundsException.class, () -> new Blake2b().update(new byte[4], 2, 3));
        // An empty key array behaves exactly like no key.
        assertEquals(hashStr(new Blake2b(), "abc"), hashStr(new Blake2b(64, new byte[0]), "abc"));
    }

    @Test
    void keyIsCopiedByTheConstructor() {
        byte[] key = seq(8);
        Blake2b b = new Blake2b(32, key);
        Blake2s s = new Blake2s(32, key);
        String bFirst = Hex.encode(b.digest());
        String sFirst = Hex.encode(s.digest());
        key[0] ^= 0x55;
        b.reset();  // reset() re-reads the stored key, so an aliased array would show the change here
        s.reset();
        assertEquals(bFirst, Hex.encode(b.digest()), "Blake2b must copy the key");
        assertEquals(sFirst, Hex.encode(s.digest()), "Blake2s must copy the key");
    }
}

package ae.hash;

import static ae.hash.TestUtil.*;
import static org.junit.jupiter.api.Assertions.*;

import java.security.MessageDigest;
import java.util.Random;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class KeccakTest {
    // Literals below come from Python hashlib (sha3_*, shake_*), generated while authoring.

    @ParameterizedTest
    @CsvSource({
        "224,e642824c3f8cf24ad09234ee7d3c766fc9a3a5168d0c94ad73b46fdf",
        "256,3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532",
        "384,ec01498288516fc926459f58e2c6ad8df9b473cb0fc08c2596da7cf0e49be4b298d88cea927ac7f539f1edf228376d25",
        "512,b751850b1a57168a5693cd924b6b096e08f621827444f70d884f5d0240d2712e10e116e9192af3c91a7ec57647e3934057340b4cf408d5a56592f8274eec53f0"})
    void sha3AbcVectors(int bits, String expected) {
        assertEquals(expected, hashStr(sha3(bits), "abc"));
    }

    static Keccak sha3(int bits) {
        return switch (bits) {
            case 224 -> Keccak.sha3_224();
            case 256 -> Keccak.sha3_256();
            case 384 -> Keccak.sha3_384();
            case 512 -> Keccak.sha3_512();
            default -> throw new IllegalArgumentException();
        };
    }

    @Test
    void sha3EmptyMessageVector() {
        assertEquals("a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a",
                hashStr(Keccak.sha3_256(), ""));
    }

    @Test
    void shakeVectors() {
        Keccak s128 = Keccak.shake128();
        s128.update("abc".getBytes());
        assertEquals("5881092dd818bf5cf8a3ddb793fbcba74097d5c526a6d35f97b83351940f2cc844c50af32acd3f2c",
                Hex.encode(s128.squeeze(40)));
        Keccak s256 = Keccak.shake256();
        assertEquals("46b9dd2b0ba88d13233b3feb743eeb243fcd52ea62b81b82b50c27646ed5762fd75dc4ddd8c0f200cb05019d67b592f6fc821c49479ab48640292eacb3b7c4be",
                Hex.encode(s256.squeeze(64)));
    }

    @Test
    void chainOfLengthsCoversEveryRateBoundary() {
        // Lengths 0..300 cross the rates 144, 136, 104, 72 (SHA3) and 168, 136 (SHAKE) at -1/0/+1.
        assertEquals("c3e220287bbbe4f55a033bf4025357172b04bb8082b2efd2e8a9cfe1", chain(Keccak.sha3_224()));
        assertEquals("8d5115b9f924b82804f0e5f484c1d89a5b4e94ff6459703f2995d140e24083a3", chain(Keccak.sha3_256()));
        assertEquals("8aed7e0100517e19cf1066cb4efe508a00bc112fa0c773bca3537b877baa8985892a2c45b9130d7030ed85104b528726", chain(Keccak.sha3_384()));
        assertEquals("e7528e9785cb60eb5c9ecd0da49f89dd27847fb2dd16965257e33bc74a7928a0b7ed9102cadd178ce54974c0354121738096e8a2382f8c21f92a6f652000e5b7", chain(Keccak.sha3_512()));
        assertEquals("4789e64a00cc848fb1a2f7b775a542e350902f815a5cd2043f2099b9988fbc37", chain(Keccak.shake128()));
        assertEquals("84901eab3e9c004ac62c6dfbebf346b37bd8cae3e2174ec2494990039cf2909a72357d0db963a541f7fc7365a3473c87b6443eec2fc43522e824f00e9419a7df", chain(Keccak.shake256()));
    }

    @Test
    void millionAs() {
        Keccak k = Keccak.sha3_256();
        byte[] block = new byte[1000];
        java.util.Arrays.fill(block, (byte) 'a');
        for (int i = 0; i < 1000; i++) {
            k.update(block);
        }
        assertEquals("5c8875ae474a3634ba4fd55ec85bffd661f32aca75c6d699d0cdcb6c115891c1", Hex.encode(k.digest()));
    }

    @Test
    void sizesAndRates() {
        assertEquals(28, Keccak.sha3_224().digestLength());
        assertEquals(144, Keccak.sha3_224().blockLength());
        assertEquals(136, Keccak.sha3_256().blockLength());
        assertEquals(104, Keccak.sha3_384().blockLength());
        assertEquals(72, Keccak.sha3_512().blockLength());
        assertEquals(168, Keccak.shake128().blockLength());
        assertEquals(136, Keccak.shake256().blockLength());
        assertEquals(32, Keccak.shake128().digestLength());
        assertEquals(64, Keccak.shake256().digestLength());
    }

    @Test
    void randomChunkingMatchesOneShotAndJdk() throws Exception {
        Random rnd = new Random(42);
        for (int iter = 0; iter < 300; iter++) {
            byte[] data = new byte[rnd.nextInt(700)];
            rnd.nextBytes(data);
            int bits = new int[] {224, 256, 384, 512}[iter % 4];
            byte[] jdk = MessageDigest.getInstance("SHA3-" + bits).digest(data);
            assertArrayEquals(jdk, chunked(sha3(bits), data, rnd), "bits=" + bits + " len=" + data.length);
        }
    }

    @Test
    void digestResetsForReuse() {
        Keccak k = Keccak.sha3_256();
        k.update("junk".getBytes());
        k.digest();
        assertEquals("3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532", hashStr(k, "abc"));
        k.update("partial".getBytes());
        k.reset();
        assertEquals("3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532", hashStr(k, "abc"));
    }

    @Test
    void shakeSqueezeIsStreamable() {
        byte[] data = msg(150);
        Keccak one = Keccak.shake128();
        one.update(data);
        byte[] all = one.squeeze(500);
        Keccak parts = Keccak.shake128();
        parts.update(data);
        byte[] joined = new byte[500];
        int[] sizes = {1, 167, 1, 168, 0, 100, 63};  // crosses the 168-byte rate repeatedly
        int pos = 0;
        for (int s : sizes) {
            byte[] p = parts.squeeze(s);
            System.arraycopy(p, 0, joined, pos, s);
            pos += s;
        }
        assertEquals(500, pos);
        assertArrayEquals(all, joined);
    }

    @Test
    void shakeLongOutputMatchesJdkFreeLiteralPrefix() {
        // Prefix property: a longer squeeze starts with the shorter one.
        Keccak a = Keccak.shake256();
        a.update("abc".getBytes());
        byte[] longOut = a.squeeze(300);
        Keccak b = Keccak.shake256();
        b.update("abc".getBytes());
        assertArrayEquals(java.util.Arrays.copyOf(longOut, 17), b.squeeze(17));
    }

    @Test
    void updateAfterSqueezeIsRejectedAndResetRecovers() {
        Keccak k = Keccak.shake128();
        k.squeeze(1);
        assertThrows(IllegalStateException.class, () -> k.update(new byte[1]));
        k.reset();
        k.update("abc".getBytes());
        assertEquals("5881092d", Hex.encode(k.squeeze(4)));
    }

    @Test
    void fixedDigestDigestAfterSqueezeIsRejected() {
        Keccak k = Keccak.sha3_256();
        assertThrows(IllegalStateException.class, () -> k.squeeze(4), "fixed-length SHA-3 is not an XOF");
    }

    @Test
    void argumentValidation() {
        Keccak k = Keccak.shake128();
        assertThrows(IllegalArgumentException.class, () -> k.squeeze(-1));
        assertThrows(NullPointerException.class, () -> Keccak.sha3_256().update(null, 0, 0));
        assertThrows(IndexOutOfBoundsException.class, () -> Keccak.sha3_256().update(new byte[4], 3, 2));
        assertThrows(IndexOutOfBoundsException.class, () -> Keccak.sha3_256().update(new byte[4], -1, 1));
    }
}

package ae.hash;

import static ae.hash.TestUtil.*;
import static org.junit.jupiter.api.Assertions.*;

import java.nio.charset.StandardCharsets;
import java.util.Random;
import javax.crypto.Mac;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import org.junit.jupiter.api.Test;

class MacTest {
    private static byte[] ascii(String s) { return s.getBytes(StandardCharsets.US_ASCII); }

    private static byte[] jdkHmac(String alg, byte[] key, byte[] msg) throws Exception {
        Mac m = Mac.getInstance(alg);
        m.init(new SecretKeySpec(key.length == 0 ? new byte[1] : key, alg));
        return m.doFinal(msg);
    }

    @Test
    void hmacSha256Rfc4231Case2() {
        assertEquals("5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843",
                Hex.encode(Hmac.mac(sha256(), ascii("Jefe"), ascii("what do ya want for nothing?"))));
    }

    @Test
    void hmacSha256Rfc4231Case6LongKey() {
        byte[] key = new byte[131];
        java.util.Arrays.fill(key, (byte) 0xaa);  // 131 > 64-byte block: key is hashed first
        assertEquals("60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54",
                Hex.encode(Hmac.mac(sha256(), key,
                        ascii("Test Using Larger Than Block-Size Key - Hash Key First"))));
    }

    @Test
    void hmacSha3AgainstJdkAcrossKeyLengthsAroundBlockSize() throws Exception {
        Random rnd = new Random(5);
        for (int keyLen : new int[] {1, 31, 135, 136, 137, 200}) {
            byte[] key = new byte[keyLen];
            rnd.nextBytes(key);
            byte[] msg = new byte[rnd.nextInt(400)];
            rnd.nextBytes(msg);
            assertArrayEquals(jdkHmac("HmacSHA3-256", key, msg), Hmac.mac(Keccak::sha3_256, key, msg), "keyLen=" + keyLen);
        }
    }

    @Test
    void hmacSha3_512LongKeyLiteralAndBlake2Literal() {
        byte[] key = new byte[200];
        for (int i = 0; i < 200; i++) {
            key[i] = (byte) i;
        }
        assertEquals("acf21f79a9f78b9b92d9bd0696004a1704ee791e7f4ef54f043e2dba9b179508bd7a16a968ac7adb9df969da5e1abd981f39e0254d6e07dc293f7c7fb189d8ae",
                Hex.encode(Hmac.mac(Keccak::sha3_512, key, ascii("hello"))));
        byte[] k = new byte[200];
        java.util.Arrays.fill(k, (byte) 'k');
        assertEquals("98de2352941a17672c6e5b8cb66ea726051e57b595399111f3a2baf3cb29ce1a78de179931c4d66f03fe4738c74bd6bd8d9ea717de572c6afd2cfa43f936eb82",
                Hex.encode(Hmac.mac(Blake2b::new, k, ascii("msg"))));
    }

    @Test
    void incrementalHmacMatchesOneShotAndResetsKeepingKey() {
        Hmac h = new Hmac(Keccak::sha3_256, ascii("key"));
        h.update(ascii("what "));
        h.update(ascii("is this"));
        byte[] first = h.doFinal();
        assertArrayEquals(Hmac.mac(Keccak::sha3_256, ascii("key"), ascii("what is this")), first);
        h.update(ascii("what is this"));
        assertArrayEquals(first, h.doFinal(), "doFinal must reset to the keyed initial state");
    }

    @Test
    void hmacEmptyKeyAndEmptyMessage() throws Exception {
        assertArrayEquals(jdkHmac("HmacSHA256", new byte[0], new byte[0]),
                Hmac.mac(sha256(), new byte[0], new byte[0]),
                "an empty key is the all-zero block");
        assertThrows(NullPointerException.class, () -> Hmac.mac(sha256(), null, new byte[0]));
    }

    @Test
    void hkdfRfc5869Case1() {
        byte[] ikm = Hex.decode("0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b");
        byte[] salt = Hex.decode("000102030405060708090a0b0c");
        byte[] info = Hex.decode("f0f1f2f3f4f5f6f7f8f9");
        byte[] prk = Hkdf.extract(sha256(), salt, ikm);
        assertEquals("077709362c2e32df0ddc3f0dc47bba6390b6c73bb50f9c3122ec844ad7c2b3e5", Hex.encode(prk));
        assertEquals("3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865",
                Hex.encode(Hkdf.expand(sha256(), prk, info, 42)));
    }

    @Test
    void hkdfRfc5869Case3EmptySaltAndInfo() {
        byte[] ikm = Hex.decode("0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b");
        byte[] prk = Hkdf.extract(sha256(), new byte[0], ikm);
        assertEquals("19ef24a32c717b167f33a91d6f648bdf96596776afdb6377ac434c1c293ccb04", Hex.encode(prk));
        assertEquals("8da4e775a563c18f715f802a063c5a31b8a11f5c5ee1879ec3454e5f3c738d2d9d201395faa4b61a96c8",
                Hex.encode(Hkdf.expand(sha256(), prk, new byte[0], 42)));
        assertArrayEquals(prk, Hkdf.extract(sha256(), null, ikm), "null salt == empty salt");
    }

    @Test
    void hkdfLengthLimits() {
        byte[] prk = new byte[32];
        assertEquals(255 * 32, Hkdf.expand(sha256(), prk, new byte[0], 255 * 32).length);
        assertThrows(IllegalArgumentException.class, () -> Hkdf.expand(sha256(), prk, new byte[0], 255 * 32 + 1));
        assertThrows(IllegalArgumentException.class, () -> Hkdf.expand(sha256(), prk, new byte[0], -1));
        assertEquals(0, Hkdf.expand(sha256(), prk, new byte[0], 0).length);
    }

    @Test
    void hkdfExpandBlocksUseCounterAfterInfo() {
        // Second block = HMAC(prk, T1 || info || 0x02): rebuild it from Hmac directly.
        byte[] prk = Hex.decode("077709362c2e32df0ddc3f0dc47bba6390b6c73bb50f9c3122ec844ad7c2b3e5");
        byte[] info = ascii("ctx");
        byte[] out = Hkdf.expand(sha256(), prk, info, 64);
        byte[] t1 = java.util.Arrays.copyOf(out, 32);
        Hmac h = new Hmac(sha256(), prk);
        h.update(t1);
        h.update(info);
        h.update(new byte[] {2});
        assertArrayEquals(h.doFinal(), java.util.Arrays.copyOfRange(out, 32, 64));
    }

    @Test
    void pbkdf2Rfc7914Vector() {
        assertEquals("55ac046e56e3089fec1691c22544b605f94185216dde0465e68b9d57c20dacbc49ca9cccf179b645991664b39d77ef317c71b845b1e30bd509112041d3a19783",
                Hex.encode(Pbkdf2.derive(sha256(), ascii("passwd"), ascii("salt"), 1, 64)));
    }

    @Test
    void pbkdf2AgainstJdk() throws Exception {
        Random rnd = new Random(11);
        for (int iter = 0; iter < 12; iter++) {
            char[] pw = ("pw" + rnd.nextInt(1000000)).toCharArray();
            byte[] salt = new byte[1 + rnd.nextInt(40)];
            rnd.nextBytes(salt);
            int c = 1 + rnd.nextInt(300);
            int dk = 1 + rnd.nextInt(100);  // spans several blocks of 32 bytes
            byte[] jdk = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")
                    .generateSecret(new PBEKeySpec(pw, salt, c, dk * 8)).getEncoded();
            assertArrayEquals(jdk, Pbkdf2.derive(sha256(), new String(pw).getBytes(StandardCharsets.UTF_8), salt, c, dk),
                    "iter=" + iter + " c=" + c + " dk=" + dk);
        }
    }

    @Test
    void pbkdf2BlockIndexUsesAllFourCounterBytes() throws Exception {
        // 8300 bytes = 260 SHA-256 blocks, so block indexes 256..260 need the second counter byte.
        byte[] jdk = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")
                .generateSecret(new PBEKeySpec("pw".toCharArray(), ascii("salt"), 1, 8300 * 8)).getEncoded();
        assertArrayEquals(jdk, Pbkdf2.derive(sha256(), ascii("pw"), ascii("salt"), 1, 8300));
    }

    @Test
    void pbkdf2WorksOverSha3AndBlake() throws Exception {
        byte[] a = Pbkdf2.derive(Keccak::sha3_256, ascii("pw"), ascii("salt"), 3, 70);
        byte[] b = Pbkdf2.derive(Blake2b::new, ascii("pw"), ascii("salt"), 3, 70);
        assertEquals(70, a.length);
        assertNotEquals(Hex.encode(a), Hex.encode(b));
        // First block with c=1 is exactly HMAC(pw, salt || 00000001).
        byte[] one = Pbkdf2.derive(Keccak::sha3_256, ascii("pw"), ascii("salt"), 1, 32);
        byte[] saltBlock = new byte[] {'s', 'a', 'l', 't', 0, 0, 0, 1};
        assertArrayEquals(jdkHmac("HmacSHA3-256", ascii("pw"), saltBlock), one);
    }

    @Test
    void pbkdf2Validation() {
        assertThrows(IllegalArgumentException.class, () -> Pbkdf2.derive(sha256(), new byte[1], new byte[1], 0, 16));
        assertThrows(IllegalArgumentException.class, () -> Pbkdf2.derive(sha256(), new byte[1], new byte[1], 1, 0));
        assertThrows(NullPointerException.class, () -> Pbkdf2.derive(sha256(), null, new byte[1], 1, 16));
    }

    @Test
    void hexStrictness() {
        assertEquals("00ff7f", Hex.encode(new byte[] {0, -1, 127}));
        assertArrayEquals(new byte[] {0, -1, 127}, Hex.decode("00FF7f"));
        assertThrows(IllegalArgumentException.class, () -> Hex.decode("abc"));
        assertThrows(IllegalArgumentException.class, () -> Hex.decode("zz"));
        assertThrows(IllegalArgumentException.class, () -> Hex.decode("0g"));
        assertEquals(0, Hex.decode("").length);
    }
}

package ae.hash;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Random;
import java.util.function.Supplier;

/** Shared helpers: chain-of-lengths fixture, random chunked hashing and a JDK digest adapter. */
final class TestUtil {
    private TestUtil() {}

    /** Message of length n with bytes (i*7+3) mod 256 (same generator as the Python literal script). */
    static byte[] msg(int n) {
        byte[] b = new byte[n];
        for (int i = 0; i < n; i++) {
            b[i] = (byte) (i * 7 + 3);
        }
        return b;
    }

    /** digest(concat(digest(msg(0)), ..., digest(msg(300)))) using one reused instance. */
    static String chain(Digest d) {
        java.io.ByteArrayOutputStream all = new java.io.ByteArrayOutputStream();
        for (int n = 0; n <= 300; n++) {
            d.update(msg(n));
            byte[] h = d.digest();
            all.write(h, 0, h.length);
        }
        d.update(all.toByteArray());
        return Hex.encode(d.digest());
    }

    static String hashStr(Digest d, String s) {
        d.update(s.getBytes(java.nio.charset.StandardCharsets.US_ASCII));
        return Hex.encode(d.digest());
    }

    /** Feeds data in random chunk sizes (including zero-length chunks). */
    static byte[] chunked(Digest d, byte[] data, Random rnd) {
        int pos = 0;
        while (pos < data.length) {
            int len = Math.min(data.length - pos, rnd.nextInt(Math.max(1, 3 * d.blockLength())));
            d.update(data, pos, len);
            pos += len;
            if (rnd.nextInt(4) == 0) {
                d.update(new byte[0], 0, 0);
            }
        }
        return d.digest();
    }

    /** Adapter that lets HMAC/HKDF/PBKDF2 run over a JDK digest (SHA-256 / SHA-512 / SHA3). */
    static final class JdkDigest implements Digest {
        private final MessageDigest md;
        private final int block;

        JdkDigest(String alg, int block) {
            try {
                this.md = MessageDigest.getInstance(alg);
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException(e);
            }
            this.block = block;
        }

        @Override public int digestLength() { return md.getDigestLength(); }
        @Override public int blockLength() { return block; }
        @Override public void update(byte[] b, int off, int len) { md.update(b, off, len); }
        @Override public byte[] digest() { return md.digest(); }
        @Override public void reset() { md.reset(); }
    }

    static Supplier<Digest> sha256() { return () -> new JdkDigest("SHA-256", 64); }
    static Supplier<Digest> sha512() { return () -> new JdkDigest("SHA-512", 128); }
}
